function bunnyGeometry() {
  const count = positions.length / 3
  let cx = 0
  let cy = 0
  let cz = 0
  for (let i = 0; i < positions.length; i += 3) {
    cx += positions[i]
    cy += positions[i + 1]
    cz += positions[i + 2]
  }
  cx /= count
  cy /= count
  cz /= count
  const uvs = []
  for (let i = 0; i < positions.length; i += 3) {
    const dx = positions[i] - cx
    const dy = positions[i + 1] - cy
    const dz = positions[i + 2] - cz
    const len = Math.hypot(dx, dy, dz) || 1
    uvs.push(0.5 + Math.atan2(dz, dx) / (Math.PI * 2), 0.5 + Math.asin(Math.max(-1, Math.min(1, dy / len))) / Math.PI)
  }
  return { positions, normals, indices, uvs }
}

export function bunnyScene() {
  return framed([{ name: 'bunny', geometry: bunnyGeometry(), color: [1, 1, 1, 1], roughness: 0.72, metallic: 0, texture: furTexture() }])
}
